import{_ as a,o as e,c as d,a3 as r}from"./chunks/framework.D1iekJsc.js";const g=JSON.parse('{"title":"ローカルモデル","description":"PC で Ollama／LM Studio／A1111／ComfyUI を起動し、スマホの MiniTavern から LAN（BYOK）接続。ローカル LLM・画像の入口。","frontmatter":{"title":"ローカルモデル","description":"PC で Ollama／LM Studio／A1111／ComfyUI を起動し、スマホの MiniTavern から LAN（BYOK）接続。ローカル LLM・画像の入口。","head":[["meta",{"name":"keywords","content":"酒場,AI酒場,MiniTavern,AI相棒,AI友達,AIローカルチャット,Silly Tavern,SillyTavern,スマホでSilly Tavern,Silly Tavernスマホ版,Silly Tavern Android,Silly Tavern iOS,AIロールプレイ,キャラクターカード,AIチャット,スマホAI,オフラインAI,AIストーリー,ローカルLLM,Ollama,LM Studio,ワールドブック,正規表現,BYOK,ユーザーガイド,マニュアル"}],["meta",{"property":"og:title","content":"ローカルモデル · MiniTavern Docs"}],["meta",{"property":"og:description","content":"PC で Ollama／LM Studio／A1111／ComfyUI を起動し、スマホの MiniTavern から LAN（BYOK）接続。ローカル LLM・画像の入口。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/ja/local"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/ja/local"}]]},"headers":[],"relativePath":"ja/local/index.md","filePath":"ja/local/index.md","lastUpdated":1787224147000}'),o={name:"ja/local/index.md"};function l(i,t,n,s,c,h){return e(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="ローカルモデル" tabindex="-1">ローカルモデル <a class="header-anchor" href="#ローカルモデル" aria-label="Permalink to &quot;ローカルモデル&quot;">​</a></h1><p>MiniTavern は <strong>BYOK</strong> クライアントです。リクエストはあなたが設定したアドレスへ送られ、特定クラウドへの強制はありません。<br> 「ローカルモデル」とは、<strong>自分の PC</strong> で推論サービスを動かし、スマホの MiniTavern から LAN でつなぐことです。</p><p>二本立て：</p><table tabindex="0"><thead><tr><th>種類</th><th>用途</th><th>入口</th></tr></thead><tbody><tr><td><strong>言語モデル</strong></td><td>チャット、続き書き、画像プロンプト変換</td><td><a href="/ultra_guides/ja/quickstart">30 分クイックスタート</a> · <a href="/ultra_guides/ja/local/tools">ツール一覧</a></td></tr><tr><td><strong>画像モデル</strong></td><td><code>/imagine</code>、添付画像、背景</td><td><a href="/ultra_guides/ja/local/image-gen/">画像概要</a></td></tr></tbody></table><p>GPU がなくサービスも入れたくない場合は、先に <a href="/ultra_guides/ja/free-cloud/">無料クラウド</a> の体験／無料枠を。</p><blockquote><p>MiniTavern は <strong>スマホ上で大規模 LLM や拡散モデルを実行しません</strong>。サービスは PC、App はキャラカード・ワールドブック・チャット・画像リクエストを担当します。</p></blockquote><h2 id="言語モデル" tabindex="-1">言語モデル <a class="header-anchor" href="#言語モデル" aria-label="Permalink to &quot;言語モデル&quot;">​</a></h2><p>PC で LLM（Ollama、LM Studio、KoboldCPP など）を起動し、App では <strong>Custom (OpenAI)</strong> を選びます。</p><table tabindex="0"><thead><tr><th>項目</th><th>推奨</th></tr></thead><tbody><tr><td>PC</td><td>Windows／macOS／Linux；メモリ <strong>16GB+</strong> 推奨</td></tr><tr><td>GPU（任意）</td><td>NVIDIA／Apple Silicon が速い；CPU のみでも可</td></tr><tr><td>ネットワーク</td><td>スマホと PC を <strong>同じ Wi‑Fi</strong>（ゲスト隔離ネットは不可）</td></tr></tbody></table><table tabindex="0"><thead><tr><th>ツール</th><th>向いている人</th><th>デフォルトポート</th></tr></thead><tbody><tr><td><a href="/ultra_guides/ja/ollama/install">Ollama</a></td><td>CLI で手軽、ワンコマンド取得</td><td><code>11434</code></td></tr><tr><td><a href="/ultra_guides/ja/lmstudio/install">LM Studio</a></td><td>GUI、クリックでダウンロード</td><td><code>1234</code></td></tr><tr><td><a href="/ultra_guides/ja/koboldcpp/install">KoboldCPP</a></td><td>ロールプレイ界隈で定番</td><td><code>5001</code></td></tr><tr><td><a href="/ultra_guides/ja/llamacpp/install">llama.cpp</a></td><td>GGUF を直接実行</td><td><code>8080</code></td></tr><tr><td><a href="/ultra_guides/ja/localai/install">LocalAI</a></td><td>Docker／互換レイヤ</td><td><code>8080</code></td></tr><tr><td><a href="/ultra_guides/ja/jan/install">Jan</a> · <a href="/ultra_guides/ja/textgen/install">text-generation-webui</a></td><td>他 GUI／プラグイン</td><td>各ページ参照</td></tr></tbody></table><p>おすすめ順：<a href="/ultra_guides/ja/quickstart">クイックスタート</a> → <a href="/ultra_guides/ja/local/tools">ツール</a> → <a href="/ultra_guides/ja/local/models">推奨モデル</a> → <a href="/ultra_guides/ja/connect-app/minitavern">MiniTavern 設定</a> → 詰まったら <a href="/ultra_guides/ja/troubleshoot">トラブルシュート</a>。</p><h2 id="画像モデル" tabindex="-1">画像モデル <a class="header-anchor" href="#画像モデル" aria-label="Permalink to &quot;画像モデル&quot;">​</a></h2><p>PC で Stable Diffusion 系を起動。App <strong>設定 → 画像生成 → 画像接続</strong> で A1111 または ComfyUI。</p><table tabindex="0"><thead><tr><th>バックエンド</th><th>デフォルトポート</th><th>チュートリアル</th></tr></thead><tbody><tr><td><a href="/ultra_guides/ja/local/image-gen/a1111">A1111／SD WebUI</a></td><td><code>7860</code></td><td><code>--api --listen</code> が必要</td></tr><tr><td><a href="/ultra_guides/ja/local/image-gen/comfyui">ComfyUI</a></td><td><code>8188</code>（Desktop は <code>8000</code> も）</td><td><code>--listen</code> が必要</td></tr></tbody></table><p>概要とハード：<a href="/ultra_guides/ja/local/image-gen/">画像モデル展開</a>；接続記入：<a href="/ultra_guides/ja/local/image-gen/connect-app">App 接続</a>。</p><h2 id="重要な注意" tabindex="-1">重要な注意 <a class="header-anchor" href="#重要な注意" aria-label="Permalink to &quot;重要な注意&quot;">​</a></h2><ul><li>スマホに入れるのは PC の <strong>LAN IP</strong>。<code>localhost</code>／<code>127.0.0.1</code> は <strong>不可</strong>。</li><li>言語モデルの Base URL は通常 <code>/v1</code> 終わり（例 <code>http://192.168.1.8:11434/v1</code>）。</li><li>A1111 は <code>--api</code> 必須；ComfyUI は LAN 到達可能であること。</li><li>ファイアウォールでポート開放；認証なし API を <strong>インターネットに晒さない</strong>。</li></ul>',17)])])}const p=a(o,[["render",l]]);export{g as __pageData,p as default};
